        return damageAmount * reimbursementRateFor(item) - DEDUCTIBLE;
    }

    private static double reimbursementRateFor(Item item) {
        if (isHighlyEnchanted(item)) {
            return REDUCED_REIMBURSEMENT;
        }
        if (isDragonMaterial(item)) {
            return FULL_REIMBURSEMENT;
        }
        return FULL_REIMBURSEMENT;
    }

    private static boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= REDUCED_REIMBURSEMENT_LEVEL;
    }

    private static boolean isDragonMaterial(Item item) {
        return DRAGON_MATERIAL.equals(item.material());
    }
}
